#include <bits/stdc++.h>
using namespace std;

int n;
vector<vector<int>> g;
vector<int> mark;
string s, ans;

void dfs(int u, int flip) {
    flip ^= mark[u];
    int color = s[u] - '0';
    if (flip & 1) color ^= 1;
    ans[u - 1] = char('0' + color);
    for (int v : g[u]) dfs(v, flip);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    g.assign(n + 1, {});
    for (int i = 2; i <= n; ++i) {
        int p;
        cin >> p;
        g[p].push_back(i);
    }

    cin >> s;
    s = " " + s;

    int q;
    cin >> q;
    mark.assign(n + 1, 0);
    while (q--) {
        int x;
        cin >> x;
        mark[x] ^= 1;
    }

    ans.assign(n, '0');
    dfs(1, 0);
    cout << ans << '\n';
    return 0;
}
